(ns fastmath.signal.denoise-test
  (:require [fastmath.signal.denoise :as sut]
            [fastmath.transform :as t]
            [clojure.test :as test]
            [clojure.java.io :as io]
            [clojure.edn :as edn]))

;; Reference values generated by `utils/fastmath/dev/generate_denoise_reference.py` into
;; `test/resources/signal/denoise_reference.edn`: MATLAB `rigrsure` (Python port) for
;; 20 inputs, threshold formulas on one coefficient vector, and 72 PyWavelets denoising
;; pipelines (db4, sym8, haar x symmetric, periodization x visu, universal, sure, hybrid
;; x hard, soft, garrote; wavedec -> pywt.threshold on detail bands -> waverec).

(def ^:private reference
  (delay (edn/read-string (slurp (io/resource "signal/denoise_reference.edn")))))

(defn- max-diff
  [a b]
  (if (= (count a) (count b))
    (reduce max 0.0 (map #(Math/abs (- (double %1) (double %2))) a b))
    Double/POSITIVE_INFINITY))

(test/deftest sure-vs-rigrsure
  (doseq [{:keys [x sure]} (:sure @reference)]
    (test/is (< (Math/abs (- sure (sut/sure x))) 1.0e-12) (str (count x) " values")))
  (test/is (== 0.5 (sut/sure [2 0.5 1 0.3 3 0.2])) "P-1 regression: was 3.0"))

(test/deftest thresholds-vs-formulas
  (let [{:keys [x] :as r} (:thresholds @reference)]
    (doseq [thr [:visu :universal :sure :hybrid :avg :peaksavg :topn]]
      (test/is (< (Math/abs (- (r thr) (sut/threshold x thr))) 1.0e-12) (str thr)))
    (test/is (== (sut/threshold x :sure) (sut/threshold x :rigrsure)))
    (test/is (== (sut/threshold x :hybrid) (sut/threshold x :heursure)))
    (test/is (== (sut/threshold x :peaksavg) (sut/threshold x :peaks-avg)))
    (test/is (== (sut/threshold x :topn 0.25) (sut/threshold x :top-n)))
    (test/is (== 1.5 (sut/threshold x 1.5)) "number passes through")
    (test/is (pos? (sut/threshold x :minfdr)))
    (test/is (pos? (sut/threshold x :minfdr-robust)))))

(test/deftest denoise-vs-pywavelets
  (let [{:keys [signal pipelines]} @reference]
    (doseq [{:keys [wavelet mode thr method lambda result]} pipelines
            :let [bands (t/dwt signal wavelet {:mode mode})
                  estimate (if (#{:visu :universal} thr) (last bands) (apply concat (rest bands)))
                  label (str wavelet " " mode " " thr " " method)]]
      (test/is (< (Math/abs (- lambda (sut/threshold estimate thr))) 1.0e-12) (str label " threshold"))
      ;; SURE returns the magnitude of one coefficient (scaled by sigma and back), so with :hard
      ;; that coefficient lies exactly at the threshold and its fate depends on the last bit
      ;; (haar: kept by PyWavelets, zeroed here); the threshold itself is checked above
      (when-not (and (= method :hard) (#{:sure :hybrid} thr))
        (test/is (< (max-diff result (sut/denoise wavelet signal {:mode mode :thr thr :method method})) 1.0e-10)
                 label)))))

(test/deftest denoise-bands-and-flat
  (let [x (map #(+ (Math/sin (* 0.2 %)) (* 0.3 (Math/cos (* 3.1 % %)))) (range 100))
        bands (t/dwt x "db2" {:level 3})
        res (sut/denoise bands {:thr 0.4 :method :soft})]
    (test/testing "bands: approximation unchanged, metadata kept"
      (test/is (= (first bands) (first res)))
      (test/is (= (meta bands) (meta res)))
      (test/is (= 100 (count (t/idwt res "db2")))))
    (test/testing "flat coefficients"
      (let [flat [0.1 -2.0 0.3 4.0 -0.2 0.05]]
        (test/is (= [0.0 -2.0 0.0 4.0 0.0 0.0] (sut/denoise flat {:thr 0.5})) "hard")
        (test/is (= [0.1 -2.0 0.0 4.0 0.0 0.0] (sut/denoise flat {:thr 0.5 :skip 1})) "skip")
        (test/is (= [0.0 -1.5 0.0 3.5 0.0 0.0] (sut/denoise flat {:thr 0.5 :method :soft})))
        (test/is (= [0.0 -1.875 0.0 3.9375 0.0 0.0] (sut/denoise flat {:thr 0.5 :method :garrote})))
        (test/is (= [0.0 (- (Math/sqrt 3.75)) 0.0 (Math/sqrt 15.75) 0.0 0.0] (sut/denoise flat {:thr 0.5 :method :hyperbole})))
        (test/is (= (vec flat) (sut/denoise flat {:thr 0.5 :skip 10})) "skip beyond length")))
    (test/testing "transformer arity"
      (let [tr (t/transformer :dwt "db2")
            r (sut/denoise tr x {:thr 0.4 :method :soft :level 3})]
        (test/is (= 100 (count r)))
        ;; transform objects give flat coefficients without band lengths: the flat rule (all after :skip) applies
        (let [flat (t/dwt x "db2" {:level 3 :flat? true})]
          (test/is (< (max-diff (t/idwt (sut/denoise (with-meta flat nil) {:thr 0.4 :method :soft}) "db2" (dissoc (::t/dwt (meta flat)) :wavelet)) r) 1e-12)))))
    (test/testing "one band (level 0): nothing changes"
      (test/is (= [(vec x)] (sut/denoise (t/dwt x "db2" {:level 0})))))))

(test/deftest guards
  (test/is (thrown? clojure.lang.ExceptionInfo (sut/sure [])))
  (test/is (thrown? clojure.lang.ExceptionInfo (sut/threshold [] :visu)))
  (test/is (thrown? clojure.lang.ExceptionInfo (sut/threshold [1 2 3] :unknown)))
  (test/is (thrown? clojure.lang.ExceptionInfo (sut/denoise [])))
  (test/is (thrown? clojure.lang.ExceptionInfo (sut/denoise [1 2 3] {:thr 1 :method :unknown})))
  (test/is (thrown? clojure.lang.ExceptionInfo (sut/denoise "db2" [] {})))
  (test/is (== 0.0 (sut/threshold [2.0 2.0 2.0] :sure)) "zero noise estimate")
  (test/is (== 0.0 (sut/threshold [0 0 0 1.0] :minfdr-robust)) "zero MAD, no NaN")
  (test/is (== 0.0 (sut/threshold [1 1 1 1.0] :minfdr)) "zero standard deviation")
  (test/is (thrown? clojure.lang.ExceptionInfo (sut/minfdr-threshold [] 0.25 false))))

(test/deftest flat-dwt-coefficients-are-bands
  (let [x [1 2 3 4 50 1 2 3 7 -2 5]
        opts {:thr :visu :method :soft}
        bands (t/dwt x "haar" {:level 2})
        flat (t/dwt x "haar" {:level 2 :flat? true})
        denoised-flat (sut/denoise flat opts)]
    (test/is (= (vec (apply concat (sut/denoise bands opts))) denoised-flat) "same shrinkage as bands")
    (test/is (= (meta flat) (meta denoised-flat)))
    (test/is (= (first bands) (subvec denoised-flat 0 (count (first bands)))) "approximation unchanged")
    (test/is (= (t/idwt (sut/denoise bands opts)) (t/idwt denoised-flat)))))

(test/deftest transformer-result-is-a-vector
  (test/is (vector? (sut/denoise (t/transformer :real :fft) (range 16) {:thr :visu}))))
